const r = $json;
const turnUrl = 'https://n8n-kmar.srv1804200.hstgr.cloud/webhook/saarthi-conv-turn';
const mode = (r.input_mode || 'record').toLowerCase();
/* Seconds of silence that end the caller's turn, and the longest
   turn we will record. Twilio's minimum silence is 1. */
const silence = Math.max(1, parseInt(r.record_silence, 10) || 1);
const maxLen = Math.max(5, parseInt(r.record_max_seconds, 10) || 20);

/* The locale Saarthi answered in, which is the one to listen in next.
   Without this the line keeps LISTENING in the language the caller has stopped
   speaking, however well the answer came back. */
const locale = { hi: 'hi-IN', en: 'en-IN', bn: 'bn-IN', ta: 'ta-IN', te: 'te-IN',
  mr: 'mr-IN', gu: 'gu-IN', kn: 'kn-IN', ml: 'ml-IN', pa: 'pa-IN', or: 'or-IN',
  as: 'as-IN', ur: 'ur-IN' }[r.language || 'hi'] || 'hi-IN';
const listen = r.listen_locale || locale;

const esc = (s) => String(s || '').replace(/[<>&'"]/g, (c) => ({ '<': '&lt;',
  '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' }[c]));
const say = r.audio_url ? `<Play>${esc(r.audio_url)}</Play>`
  : `<Say language="${locale}">${esc(r.reply)}</Say>`;

let twiml;
if (mode === 'gather') {
  /* Twilio's own recognition. Fast, and limited to the one locale this Gather
     is opened with - which is the whole reason for the other path.
     actionOnEmptyResult keeps the call alive when the farmer says nothing:
     Twilio posts back with an empty SpeechResult and Saarthi asks them to
     repeat, instead of hanging up on a moment of hesitation. */
  twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Gather input="speech" speechTimeout="auto" speechModel="experimental_conversations" language="${listen}" actionOnEmptyResult="true" action="${turnUrl}" method="POST">
    ${say}
  </Gather>
</Response>`;
} else {
  /* The caller's own audio, for Azure to identify and transcribe.
     - playBeep false: a beep every turn makes a conversation feel like a
       voicemail, which is not what this is.
     - timeout: how much silence ends the turn, from record_silence on the
       Config node. ONE second, not three. Three seconds of dead air after
       the farmer has already finished is the largest single piece of the
       wait, on every turn, and the caller spends it wondering whether the
       line has dropped. One is what a question-and-answer line wants; raise
       it on the Config node for somebody who thinks out loud.
     - maxLength 30: nobody asks a farming question for half a minute, and an
       open microphone that never closes is a bill and a privacy cost.
     - trim-silence: less to upload, and Azure gets the speech rather than the
       room. */
  twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  ${say}
  <Record action="${turnUrl}" method="POST" maxLength="${maxLen}" timeout="${silence}" playBeep="false" trim="trim-silence" />
  <!-- Twilio does NOT post to the action when nothing at all was recorded; it
       falls through to the next verb instead. Without this the call would go
       quiet the first time somebody hesitated. The Redirect brings the turn
       back with no transcript and no audio, and Saarthi nudges them. -->
  <Redirect method="POST">${turnUrl}</Redirect>
</Response>`;
}
return [{ json: { twiml } }];

