</Response>`;
}
return [{ json: { twiml } }];

/* Everything Saarthi needs for one turn, in one place.

   `audio_b64` is the point of it: with the caller's own audio, Azure
   identifies the language from the sound rather than from a transcript that
   was written down by whichever engine the line happened to open with. With no
   audio the turn still works - the server reads the script of the transcript,
   which settles eleven of the thirteen on its own. */
const cfg = $('Config turn - EDIT ME').first().json;
const body = cfg.body || {};
const item = $input.first();

const outbound = String(body.Direction || '').startsWith('outbound');
const payload = {
  phone: outbound ? body.To : body.From,
  call_id: body.CallSid,
  transcript: body.SpeechResult || '',
  language: cfg.language || 'hi',
  resumed: true,
  speak: true,
  direction: body.Direction || 'inbound',
};

/* The recording, as base64.

   NOT `item.binary.recording.data`. That is only the base64 when n8n is
   holding binaries in memory; with the filesystem store - which is the
   default here - it is an ID, and sending it produced a cheerful HTTP 422
   from Azure and a call that quietly stayed in one language.
   `getBinaryDataBuffer` reads the real bytes either way.

   A recording Twilio had not finished writing yet simply is not here, and the
   turn carries on without it. */
const recording = item.binary && item.binary.recording;
if (recording) {
  let bytes = null;
  try {
    bytes = await this.helpers.getBinaryDataBuffer(0, 'recording');
  } catch (err) {
    bytes = recording.data ? Buffer.from(recording.data, 'base64') : null;
  }
  if (bytes && bytes.length > 1000) {
    payload.audio_b64 = bytes.toString('base64');
    payload.audio_type = recording.mimeType || 'audio/wav';
    payload.audio_name = 'turn.wav';
    payload.audio_bytes = bytes.length;
  }
}

return [{ json: { saarthi_base: cfg.saarthi_base, saarthi_token: cfg.saarthi_token,
                  payload } }];
